package clientgen

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/joakimcarlsson/minmux/clientgen/internal/runtime"
)

// generator holds the state of one generation run.
type generator struct {
	cfg         Config
	reg         *registry
	typeNames   *nameSet
	methodNames *nameSet
	ops         []*operation
}

// Render produces the generated files in memory without touching the
// filesystem. Useful for tests and for callers that want to write the
// output somewhere other than a directory.
func Render(cfg Config) ([]File, error) {
	if err := cfg.normalize(); err != nil {
		return nil, err
	}
	g := &generator{
		cfg:         cfg,
		reg:         newRegistry(),
		methodNames: newNameSet(reservedNames),
	}
	g.reg.declare(cfg.Spec)
	g.typeNames = g.reg.names

	if err := g.reg.build(cfg.Spec); err != nil {
		return nil, fmt.Errorf("clientgen: %w", err)
	}
	ops, err := g.buildOperations()
	if err != nil {
		return nil, fmt.Errorf("clientgen: %w", err)
	}
	g.ops = ops

	files := []File{
		{Name: "client.gen.go", Content: g.renderRuntime()},
		{Name: "types.gen.go", Content: g.renderTypes()},
		{Name: "operations.gen.go", Content: g.renderOperations()},
	}
	for i, f := range files {
		formatted, err := format.Source(f.Content)
		if err != nil {
			return nil, fmt.Errorf(
				"clientgen: formatting %s: %w\n%s", f.Name, err, f.Content,
			)
		}
		files[i].Content = formatted
	}
	return files, nil
}

// Generate renders the client and writes it to cfg.Out, creating the
// directory if needed and removing any stale file from a previous run.
//
// Output is byte-stable for a given spec, so regenerating an unchanged API
// leaves the working tree clean.
func Generate(cfg Config) error {
	files, err := Render(cfg)
	if err != nil {
		return err
	}
	if cfg.Out == "" {
		return fmt.Errorf("clientgen: Config.Out is required")
	}
	if err := os.MkdirAll(cfg.Out, 0o755); err != nil {
		return fmt.Errorf("clientgen: creating %s: %w", cfg.Out, err)
	}
	if err := pruneStale(cfg.Out); err != nil {
		return err
	}
	for _, f := range files {
		path := filepath.Join(cfg.Out, f.Name)
		if err := os.WriteFile(path, f.Content, 0o644); err != nil {
			return fmt.Errorf("clientgen: writing %s: %w", path, err)
		}
	}
	return nil
}

// pruneStale removes *.gen.go files this run will not rewrite, so a
// renamed or dropped output file cannot linger and keep compiling.
func pruneStale(dir string) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return fmt.Errorf("clientgen: reading %s: %w", dir, err)
	}
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".gen.go") {
			continue
		}
		if slices.Contains(generatedFileNames, e.Name()) {
			continue
		}
		path := filepath.Join(dir, e.Name())
		if err := os.Remove(path); err != nil {
			return fmt.Errorf("clientgen: removing stale %s: %w", path, err)
		}
	}
	return nil
}

// renderRuntime re-emits the compiled internal/runtime package into the
// target package, rewriting its package clause and its "client:" error
// prefix to match the generated package name.
func (g *generator) renderRuntime() []byte {
	src := runtime.Source
	if i := strings.Index(src, "\npackage runtime\n"); i >= 0 {
		src = src[i+len("\npackage runtime\n"):]
	} else {
		src = strings.TrimPrefix(src, "package runtime\n")
	}
	src = strings.ReplaceAll(src, `"client: `, `"`+g.cfg.Package+`: `)
	src = strings.ReplaceAll(
		src,
		"type Client struct",
		"type "+g.clientType()+" struct",
	)
	src = strings.ReplaceAll(src, "(c *Client)", "(c *"+g.clientType()+")")
	src = strings.ReplaceAll(
		src,
		"*Client, error)",
		"*"+g.clientType()+", error)",
	)
	src = strings.ReplaceAll(src, "func(*Client)", "func(*"+g.clientType()+")")
	src = strings.ReplaceAll(src, "c := &Client{", "c := &"+g.clientType()+"{")

	var b bytes.Buffer
	g.writeHeader(&b)
	b.WriteString(strings.TrimLeft(src, "\n"))
	return b.Bytes()
}

func (g *generator) clientType() string { return g.cfg.ClientName }

func (g *generator) writeHeader(b *bytes.Buffer) {
	fmt.Fprintf(b, "// Code generated by %s. DO NOT EDIT.\n\n", g.cfg.Command)
	fmt.Fprintf(b, "package %s\n\n", g.cfg.Package)
}

// stdImports is the closed set of standard-library packages generated code
// can reference. Imports are selected by scanning the rendered body for
// each package's qualifier, which keeps the emitter from having to thread
// an import set through every call site.
var stdImports = []string{
	"bufio",
	"bytes",
	"context",
	"encoding/json",
	"errors",
	"fmt",
	"io",
	"iter",
	"maps",
	"mime",
	"mime/multipart",
	"net/http",
	"net/textproto",
	"net/url",
	"slices",
	"strconv",
	"strings",
	"time",
}

// importsFor returns the subset of stdImports the body actually
// references, in sorted order.
func importsFor(body string) []string {
	var out []string
	for _, path := range stdImports {
		qualifier := path
		if i := strings.LastIndexByte(path, '/'); i >= 0 {
			qualifier = path[i+1:]
		}
		if strings.Contains(body, qualifier+".") {
			out = append(out, path)
		}
	}
	slices.Sort(out)
	return out
}

func (g *generator) renderFile(body string) []byte {
	var b bytes.Buffer
	g.writeHeader(&b)
	if imports := importsFor(body); len(imports) > 0 {
		b.WriteString("import (\n")
		for _, path := range imports {
			fmt.Fprintf(&b, "\t%q\n", path)
		}
		b.WriteString(")\n\n")
	}
	b.WriteString(body)
	return b.Bytes()
}
